// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address from, address to, uint256 value) public {
        vm.assume(from != address(0));
        // Call allowance - the bug causes revert when calling from non-owner in auth-modifier but allowance is not auth-protected
        // However, the bug is in file() which is not called here, so we need to trigger file() indirectly
        // The rule: calling file() should never revert when called by an authorized user (wards[msg.sender]==1)
        // Since we are the owner (setUp gave us ward), file() should succeed
        // But the bug changes auth to require wards[msg.sender]==0, causing revert
        // So we test that file() does not revert
        // Use try/catch to catch revert
        bool reverted = false;
        try c.file("investmentManager", address(this)) {
            // success
        } catch {
            reverted = true;
        }
        assertTrue(!reverted, "file() should not revert when called by owner");
    }
}

